/// Guaranteed-covered disk radius around the origin per generation
/// depth (measured: gen2 111.30 by boundary census and polar
/// sampling; growth measured 8.18x per generation; the table uses
/// a conservative 8.0).  Depth selection starts at the first k
/// with COVERED[k] >= the view corner distance, then the exact
/// clipped-area acceptance escalates if the estimate was optimistic.
const COVERED: [f64; 13] = [
    0.0,
    0.0,
    111.0,
    888.0,
    7104.0,
    56832.0,
    454656.0,
    3637248.0,
    29097984.0,
    232783872.0,
    1862270976.0,
    14898167808.0,
    119185342464.0,
];

/// Maximum substitution depth.  At depth 12 the covered disk radius is
/// ≈ 1.2e11 world units; K coefficients grow ≈ 8.5× per generation from
/// the generation-2 maximum of 4720, staying below ~5e13 at depth 12
/// (worst-case bound ×10/level), so the largest raw product inside a
/// `kmul` (~3e16) is two orders of magnitude inside i64::MAX.
const MAX_DEPTH: usize = 12;

// ===== exact arithmetic in K = Q(a), a = 2cos(pi/10) =====

/// A K element: c0 + c1·a + c2·a² + c3·a³, divided by the global
/// denominator 64.  All construction quantities have true denominators
/// dividing 8, so products have denominators dividing 64 and the fixed
/// point representation is closed under the operations used here.
type Ke = [i64; 4];

/// A point with K coordinates.
type Kp = (Ke, Ke);

const ZERO: Ke = [0, 0, 0, 0];

#[inline]
fn kadd(x: Ke, y: Ke) -> Ke {
    [x[0] + y[0], x[1] + y[1], x[2] + y[2], x[3] + y[3]]
}

#[inline]
fn kmul(x: Ke, y: Ke) -> Ke {
    let p0 = x[0] * y[0];
    let p1 = x[0] * y[1] + x[1] * y[0];
    let p2 = x[0] * y[2] + x[1] * y[1] + x[2] * y[0];
    let p3 = x[0] * y[3] + x[1] * y[2] + x[2] * y[1] + x[3] * y[0];
    let p4 = x[1] * y[3] + x[2] * y[2] + x[3] * y[1];
    let p5 = x[2] * y[3] + x[3] * y[2];
    let p6 = x[3] * y[3];
    // reductions: a^4 = 5a^2 - 5, a^5 = 5a^3 - 5a, a^6 = 20a^2 - 25
    let c0 = p0 - 5 * p4 - 25 * p6;
    let c1 = p1 - 5 * p5;
    let c2 = p2 + 5 * p4 + 20 * p6;
    let c3 = p3 + 5 * p5;
    debug_assert!(
        c0 % 64 == 0 && c1 % 64 == 0 && c2 % 64 == 0 && c3 % 64 == 0,
        "K product left the fixed denominator"
    );
    [c0 / 64, c1 / 64, c2 / 64, c3 / 64]
}

/// Float value of a K element (used for window tests and emission; all
/// comparisons that matter for correctness are exact tuple tests).
#[inline]
fn kval(x: Ke) -> f64 {
    (x[0] as f64 + x[1] as f64 * A + x[2] as f64 * A2 + x[3] as f64 * A3) / 64.0
}

#[inline]
fn pval(p: Kp) -> (f64, f64) {
    (kval(p.0), kval(p.1))
}

/// Apply the exact rotation matrix `ROTM[r]` to a point.
#[inline]
fn rot_kp(r: usize, p: Kp) -> Kp {
    let m = &ROTM[r];
    (
        kadd(kmul(m[0][0], p.0), kmul(m[0][1], p.1)),
        kadd(kmul(m[1][0], p.0), kmul(m[1][1], p.1)),
    )
}

// ===== substitution objects =====

/// One object of the recursion: a tile (type 1 HEX, 2 BOW, 3 DEC) or an
/// edge marker (type 0), its rotation in 18° units, and its exact centre.
#[derive(Clone, Copy)]
struct Obj {
    ty: u8,
    rot: u8,
    pos: Kp,
}

fn real_table(ty: u8) -> &'static [(u8, u8, [i64; 4], [i64; 4])] {
    match ty {
        1 => &REAL_HEX,
        2 => &REAL_BOW,
        3 => &REAL_DEC,
        _ => unreachable!("no real table for type {ty}"),
    }
}

fn mark_table(ty: u8) -> &'static [(u8, [i64; 4], [i64; 4])] {
    match ty {
        1 => &MARK_HEX,
        2 => &MARK_BOW,
        3 => &MARK_DEC,
        _ => unreachable!("no marker table for type {ty}"),
    }
}

/// Substitute every object once: real tiles expand to their child cluster
/// plus edge markers, edge markers expand to the straddling trio.
fn inflate_into(objs: &[Obj], out: &mut Vec<Obj>) {
    for &o in objs {
        let r = o.rot as usize;
        let base = (kmul(IFK, o.pos.0), kmul(IFK, o.pos.1));
        if o.ty == 0 {
            for i in 0..3 {
                let off = rot_kp(r, EDGE_RULE_OFF[i]);
                out.push(Obj {
                    ty: EDGE_RULE_TY[i],
                    rot: (o.rot + EDGE_RULE_ROT[i]) % 20,
                    pos: (kadd(base.0, off.0), kadd(base.1, off.1)),
                });
            }
        } else {
            for &(ct, cr, ox, oy) in real_table(o.ty) {
                let off = rot_kp(r, (ox, oy));
                out.push(Obj {
                    ty: ct,
                    rot: (o.rot + cr) % 20,
                    pos: (kadd(base.0, off.0), kadd(base.1, off.1)),
                });
            }
            for &(mr, mx, my) in mark_table(o.ty) {
                let mid = rot_kp(r, (mx, my));
                out.push(Obj {
                    ty: 0,
                    rot: (o.rot + mr) % 20,
                    pos: (kadd(base.0, mid.0), kadd(base.1, mid.1)),
                });
            }
        }
    }
}

/// The seed lineage: one unit decagon at the origin (rotation 0) plus its
/// 10 boundary edges as markers.
fn seed_objs() -> [Obj; 11] {
    let mut s = [Obj {
        ty: 3,
        rot: 0,
        pos: (ZERO, ZERO),
    }; 11];
    for (i, &(mr, mx, my)) in SEED_EDGES.iter().enumerate() {
        s[i + 1] = Obj {
            ty: 0,
            rot: mr,
            pos: (mx, my),
        };
    }
    s
}

// ===== view-driven generation =====

/// Margin added to the view box at the emitted depth: any tile
/// intersecting the view has its centre within φ ≈ 1.6181 of the box.
const EMIT_MARGIN: f64 = 1.75;

/// Inter-level window margin: children of an object lie within
/// 13.307 (child units) of IF·(parent centre), so a parent of any child
/// in window W lies within W/IF ± 13.307/IF = 1.5705.
const INTER_MARGIN: f64 = 1.6;

type Box4 = (f64, f64, f64, f64);

#[inline]
fn in_box(o: &Obj, b: Box4) -> bool {
    let (x, y) = pval(o.pos);
    b.0 <= x && x <= b.1 && b.2 <= y && y <= b.3
}

fn obj_key(o: &Obj) -> [i64; 10] {
    [
        o.ty as i64,
        o.rot as i64,
        o.pos.0[0],
        o.pos.0[1],
        o.pos.0[2],
        o.pos.0[3],
        o.pos.1[0],
        o.pos.1[1],
        o.pos.1[2],
        o.pos.1[3],
    ]
}

/// Build the generation-`depth` real tiles whose centres lie within
/// `region` (padded by [`EMIT_MARGIN`]) via the S-box window cascade:
/// window *j* is window *j+1* shrunk by IF and padded by
/// [`INTER_MARGIN`], which provably retains every object with a
/// descendant in the emitted window.
fn build_reals(depth: usize, region: Box4) -> Vec<Obj> {
    let mut w: Vec<Box4> = vec![(0.0, 0.0, 0.0, 0.0); depth + 1];
    w[depth] = (
        region.0 - EMIT_MARGIN,
        region.1 + EMIT_MARGIN,
        region.2 - EMIT_MARGIN,
        region.3 + EMIT_MARGIN,
    );
    for j in (1..depth).rev() {
        let b = w[j + 1];
        w[j] = (
            b.0 / IF_F - INTER_MARGIN,
            b.1 / IF_F + INTER_MARGIN,
            b.2 / IF_F - INTER_MARGIN,
            b.3 / IF_F + INTER_MARGIN,
        );
    }
    let mut cur: Vec<Obj> = Vec::with_capacity(1024);
    inflate_into(&seed_objs(), &mut cur);
    for j in 2..=depth {
        let wm = w[j - 1];
        cur.retain(|o| in_box(o, wm));
        let mut next: Vec<Obj> = Vec::with_capacity(cur.len() * 8);
        inflate_into(&cur, &mut next);
        let we = w[j];
        next.retain(|o| in_box(o, we));
        cur = next;
    }
    // Real tiles only.  The substitution is duplicate-free (verified
    // exactly at generations 1 and 2); the set filter is a safeguard.
    let mut seen: HashSet<[i64; 10]> = HashSet::with_capacity(cur.len());
    cur.retain(|o| o.ty != 0 && seen.insert(obj_key(o)));
    cur
}

/// Float polygon of a tile.
fn poly_pts(o: &Obj) -> Vec<Vec2> {
    let (px, py) = pval(o.pos);
    let m = &ROT_F[o.rot as usize];
    locals_f(o.ty)
        .iter()
        .map(|&(lx, ly)| Vec2::new(px + m[0] * lx + m[1] * ly, py + m[2] * lx + m[3] * ly))
        .collect()
}

/// Float local vertices of a prototile (0 EDGE, 1 HEX, 2 BOW, 3 DEC).
fn locals_f(ty: u8) -> &'static [(f64, f64)] {
    match ty {
        0 => &EDGE_F,
        1 => &HEX_F,
        2 => &BOW_F,
        3 => &DEC_F,
        _ => unreachable!("no vertices for type {ty}"),
    }
}

/// Output prototile index of a tile type (main/largest tile first):
/// DEC -> 0, HEX -> 1, BOW -> 2.
fn proto_of(ty: u8) -> u8 {
    match ty {
        3 => 0,
        1 => 1,
        2 => 2,
        _ => unreachable!("cannot emit a marker"),
    }
}

/// Total area of `polys` (tiling coordinates) inside `region`.  Interior
/// tiles (aabb inside the region) contribute their full area; boundary
/// tiles are clipped with Sutherland–Hodgman, which is exact for the
/// girih prototiles: the two concave bow-tie lobes stay connected under
/// any single half-plane cut, so the bridged clip polygon's overlapping
/// edges cancel in the shoelace sum (verified against triangulated
/// clipping over 4000 randomized rotated bow-tie/box clips, max
/// deviation 4.4e-16).
fn clipped_patch_area(polys: &[Vec<Vec2>], region: &BBox) -> f64 {
    let mut total = 0.0;
    for pts in polys {
        let poly = Polygon::from_slice(pts);
        let bb = poly.aabb();
        if !bb.intersects(*region) {
            continue;
        }
        if region.min.x <= bb.min.x
            && region.min.y <= bb.min.y
            && region.max.x >= bb.max.x
            && region.max.y >= bb.max.y
        {
            total += poly.area();
        } else if let Some(c) = poly.clipped_to(region) {
            total += c.area();
        }
    }
    total
}

/// Girih star-and-cross (quasiperiodic; Darb-i Imam substitution).
pub struct GirihQuasiperiodicTiling;

impl Tiling for GirihQuasiperiodicTiling {
    fn id(&self) -> &'static str {
        "girih-quasiperiodic"
    }

    fn name(&self) -> &'static str {
        "Girih Star-and-Cross (quasiperiodic)"
    }

    fn description(&self) -> &'static str {
        "Quasiperiodic girih star-and-cross generated by the 3-prototile Darb-i Imam substitution (Lu & Steinhardt 2007): decagon, bobbin and bow-tie, inflation 2(2+√5) = 2φ³, exact 10-fold rosette around the seed decagon, edge-to-edge and T-junction-free at every generation."
    }

    fn category(&self) -> TilingCategory {
        TilingCategory::Quasiperiodic
    }

    fn params(&self) -> &'static [ParamSpec] {
        &SIMILARITY_PARAMS
    }

    fn default_color_mode(&self) -> ColorMode {
        ColorMode::Proto
    }

    fn generate(&self, params: &ParamSet, query: &Query) -> TilingResult {
        let meta = SymmetryMeta::new(WallpaperGroup::P1, LatticeKind::None).with_notes(
            "quasiperiodic; Darb-i Imam substitution; inflation 2*phi^3; edge-to-edge; 10-fold seed rosette",
        );
        let fail = |message: &'static str| TilingResult {
            tiles: Vec::new(),
            symmetry: meta,
            periodic: None,
            message: Some(message),
        };

        let map = similarity_map(params);
        let inv = map.inverse();

        // Region in the tiling's own (unit-edge) coordinates: the box
        // around the inverse images of the world corners.
        let mut rmin = Vec2::new(f64::MAX, f64::MAX);
        let mut rmax = Vec2::new(f64::MIN, f64::MIN);
        for &corner in &query.region.corners() {
            let q = inv.transform(corner);
            rmin.x = rmin.x.min(q.x);
            rmin.y = rmin.y.min(q.y);
            rmax.x = rmax.x.max(q.x);
            rmax.y = rmax.y.max(q.y);
        }
        let region = BBox::new(rmin, rmax);
        if region.area() <= 1e-12 {
            return fail("empty view");
        }
        // Tiles are unit-edge with mean area MEAN_AREA at the substitution
        // frequencies, so this bounds the tile count before any work.
        if region.area() > MAX_TILES as f64 * MEAN_AREA {
            return fail("too many tiles for this view — zoom in");
        }

        // Farthest corner from the seed (the origin) picks the starting
        // depth from the conservative covered-radius table.
        let mut rcorr = 0.0f64;
        for &corner in &query.region.corners() {
            let q = inv.transform(corner);
            rcorr = rcorr.max(q.x.hypot(q.y));
        }
        let mut start = 2;
        while start < MAX_DEPTH && COVERED[start] < rcorr {
            start += 1;
        }
        if COVERED[start] < rcorr {
            return fail("too many tiles for this view — zoom in");
        }

        let want = region.area();
        let region4 = (region.min.x, region.max.x, region.min.y, region.max.y);
        let mut found: Option<Vec<Obj>> = None;
        for depth in start..=MAX_DEPTH {
            let reals = build_reals(depth, region4);
            if reals.is_empty() {
                continue;
            }
            let polys: Vec<Vec<Vec2>> = reals.iter().map(poly_pts).collect();
            // Acceptance is exact: the patch must cover the (padded)
            // region box with no gaps and no overlaps.  A depth whose
            // patch does not reach far enough fails and the next depth
            // is tried.
            if clipped_patch_area(&polys, &region) >= want * (1.0 - 1e-9) {
                found = Some(reals);
                break;
            }
        }
        let reals = match found {
            Some(r) => r,
            None => return fail("too many tiles for this view — zoom in"),
        };

        // Emit exactly the tiles intersecting the query region.
        let mut tiles = Vec::with_capacity(reals.len());
        for o in &reals {
            let pts = poly_pts(o);
            let poly = Polygon::from_slice(&pts).transform(&map);
            if poly.aabb().intersects(query.region) {
                let proto = proto_of(o.ty);
                tiles.push(Tile { family: tess_core::tiling::FamilyTag::None, reflected: false,
                    proto,
                    seed: proto as u32, level: 0,
                    poly,
                });
            }
        }
        if tiles.len() > MAX_TILES {
            return fail("too many tiles for this view — zoom in");
        }

        TilingResult {
            tiles,
            symmetry: meta,
            periodic: None,
            message: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::{BTreeMap, BTreeSet, HashMap};

    const ONE: Ke = [64, 0, 0, 0];
    const HALF: Ke = [32, 0, 0, 0];

    fn kneg(x: Ke) -> Ke {
        [-x[0], -x[1], -x[2], -x[3]]
    }

    fn ksub(x: Ke, y: Ke) -> Ke {
        [x[0] - y[0], x[1] - y[1], x[2] - y[2], x[3] - y[3]]
    }

    fn padd(p: Kp, q: Kp) -> Kp {
        (kadd(p.0, q.0), kadd(p.1, q.1))
    }

    fn psub(p: Kp, q: Kp) -> Kp {
        (
            [
                p.0[0] - q.0[0],
                p.0[1] - q.0[1],
                p.0[2] - q.0[2],
                p.0[3] - q.0[3],
            ],
            [
                p.1[0] - q.1[0],
                p.1[1] - q.1[1],
                p.1[2] - q.1[2],
                p.1[3] - q.1[3],
            ],
        )
    }

    fn pcross(p: Kp, q: Kp) -> Ke {
        ksub(kmul(p.0, q.1), kmul(p.1, q.0))
    }

    fn pdot(p: Kp, q: Kp) -> Ke {
        kadd(kmul(p.0, q.0), kmul(p.1, q.1))
    }

    fn is_zero(x: Ke) -> bool {
        x == ZERO
    }

    fn verts_of(ty: u8) -> &'static [Kp] {
        match ty {
            0 => &EDGE_V,
            1 => &HEX_V,
            2 => &BOW_V,
            3 => &DEC_V,
            _ => unreachable!(),
        }
    }

    /// Canonical unit direction of class `r` (the first column of ROTM).
    fn canon(r: usize) -> Kp {
        (ROTM[r][0][0], ROTM[r][1][0])
    }

    /// Exact direction class of a K vector, or -1 if not canonical.
    fn dir_class(v: Kp) -> i32 {
        for r in 0..20 {
            if v == canon(r) {
                return r as i32;
            }
        }
        -1
    }

    fn tile_verts(ty: u8, rot: u8, pos: Kp) -> Vec<Kp> {
        verts_of(ty)
            .iter()
            .map(|&v| padd(pos, rot_kp(rot as usize, v)))
            .collect()
    }

    /// Exact unit-edge check for every prototile.
    #[test]
    fn prototiles_are_exact_unit_edge() {
        for ty in [0u8, 1, 2, 3] {
            let vs = verts_of(ty);
            let n = vs.len();
            for i in 0..n {
                let e = psub(vs[(i + 1) % n], vs[i]);
                assert_eq!(pdot(e, e), ONE, "type {ty} edge {i} not unit");
            }
        }
        // spot checks: R_5 is exactly +90 degrees, R_10 exactly 180
        assert_eq!(ROTM[5][0][0], ZERO);
        assert_eq!(ROTM[5][1][0], ONE);
        assert_eq!(ROTM[10][0][0], kneg(ONE));
        assert_eq!(ROTM[10][1][1], kneg(ONE));
        // float evaluation agrees with the exact constants
        assert!((kval(HALF) - 0.5).abs() < 1e-15);
        assert!(
            (kval(EDGE_RULE_OFF[2].0) - 2.9270509831248423).abs() < 1e-12,
            "edge-rule offset"
        );
        assert!((IF_F - 2.0 * (2.0 + 5.0f64.sqrt())).abs() < 1e-12);
    }

    /// Straddler trio placements on a parent boundary edge (mid, cls):
    /// the same rule as an edge marker's substitution.
    fn boundary_trio(mid: Kp, cls: u8) -> Vec<Obj> {
        let base = (kmul(IFK, mid.0), kmul(IFK, mid.1));
        (0..3)
            .map(|i| {
                let off = rot_kp(cls as usize, EDGE_RULE_OFF[i]);
                Obj {
                    ty: EDGE_RULE_TY[i],
                    rot: (cls + EDGE_RULE_ROT[i]) % 20,
                    pos: (kadd(base.0, off.0), kadd(base.1, off.1)),
                }
            })
            .collect()
    }

    /// The closed cluster of a parent type: real children plus the trios
    /// on the parent's own boundary edges.
    fn closed_cluster(ty: u8) -> Vec<Obj> {
        let mut out: Vec<Obj> = real_table(ty)
            .iter()
            .map(|&(ct, cr, ox, oy)| Obj {
                ty: ct,
                rot: cr,
                pos: (ox, oy),
            })
            .collect();
        let vs = verts_of(ty);
        let n = vs.len();
        for i in 0..n {
            let a = vs[i];
            let b = vs[(i + 1) % n];
            let cls = dir_class(psub(b, a));
            assert!(cls >= 0, "parent {ty} boundary edge not canonical");
            let mid = padd(a, rot_kp(cls as usize, (HALF, ZERO)));
            out.extend(boundary_trio(mid, cls as u8));
        }
        out
    }

    /// The substitution tables close exactly: for each parent type the
    /// closed cluster is a duplicate-free valid tiling whose interior
    /// edges are exactly the marker table, bijectively.
    #[test]
    fn substitution_tables_close_exactly() {
        for ty in [1u8, 2, 3] {
            let cluster = closed_cluster(ty);
            // no duplicate cluster tiles
            let mut seen: HashSet<[i64; 10]> = HashSet::new();
            let n_dup = cluster.iter().filter(|o| !seen.insert(obj_key(o))).count();
            assert_eq!(n_dup, 0, "parent {ty}: duplicate cluster tiles");

            // undirected edge census
            let mut edges: BTreeMap<(Kp, Kp), u32> = BTreeMap::new();
            for o in &cluster {
                let vs = tile_verts(o.ty, o.rot, o.pos);
                let n = vs.len();
                for i in 0..n {
                    let (a, b) = (vs[i], vs[(i + 1) % n]);
                    assert_eq!(pdot(psub(b, a), psub(b, a)), ONE, "edge not unit");
                    let key = if a <= b { (a, b) } else { (b, a) };
                    *edges.entry(key).or_insert(0) += 1;
                }
            }
            assert!(
                edges.values().all(|&c| c <= 2),
                "parent {ty}: edge multiplicity > 2"
            );
            let interior: BTreeSet<(Kp, Kp)> = edges
                .iter()
                .filter(|(_, &c)| c == 2)
                .map(|(&k, _)| k)
                .collect();

            // markers reconstruct exactly the interior edge set
            let marks: BTreeSet<(Kp, Kp)> = mark_table(ty)
                .iter()
                .map(|&(mr, mx, my)| {
                    let mid = (mx, my);
                    let h = rot_kp(mr as usize, (HALF, ZERO));
                    let a = psub(mid, h);
                    let b = padd(mid, h);
                    if a <= b {
                        (a, b)
                    } else {
                        (b, a)
                    }
                })
                .collect();
            assert_eq!(
                marks.len(),
                mark_table(ty).len(),
                "parent {ty}: duplicate markers"
            );
            assert_eq!(
                marks, interior,
                "parent {ty}: markers != interior edges of the closed cluster"
            );

            // offset bounds used by the window cascade margins
            for &(_, _, ox, oy) in real_table(ty) {
                let (x, y) = pval((ox, oy));
                assert!(
                    x * x + y * y < 12.5 * 12.5,
                    "parent {ty}: real offset too large"
                );
            }
            for &(mr, mx, my) in mark_table(ty) {
                let (x, y) = pval((mx, my));
                assert!(
                    x * x + y * y < 13.31 * 13.31,
                    "parent {ty}: marker offset too large"
                );
                let _ = mr;
            }
        }
    }

    /// Directed-edge census of a patch: unit edges, no same-direction
    /// duplicates, every interior edge matched with opposite orientation.
    /// Returns (directed edge multiset, vertex set, boundary edge count).
    fn edge_census(reals: &[Obj]) -> (BTreeMap<(Kp, Kp), u32>, BTreeSet<Kp>, usize) {
        let mut edges: BTreeMap<(Kp, Kp), u32> = BTreeMap::new();
        let mut verts: BTreeSet<Kp> = BTreeSet::new();
        for o in reals {
            let vs = tile_verts(o.ty, o.rot, o.pos);
            let n = vs.len();
            for i in 0..n {
                let (a, b) = (vs[i], vs[(i + 1) % n]);
                assert_eq!(pdot(psub(b, a), psub(b, a)), ONE, "edge not unit");
                assert_eq!(
                    edges.insert((a, b), 1),
                    None,
                    "same-direction edge duplicated"
                );
                verts.insert(a);
                verts.insert(b);
            }
        }
        let mut matched = 0;
        let mut boundary = 0;
        for (k, &c) in edges.iter() {
            assert_eq!(c, 1);
            if edges.contains_key(&(k.1, k.0)) {
                matched += 1;
            } else {
                boundary += 1;
            }
        }
        assert_eq!(matched + boundary, edges.len(), "directed edge accounting");
        assert_eq!(matched % 2, 0, "matched edges must come in pairs");
        (edges, verts, boundary)
    }

    /// Exact T-junction check: no vertex lies strictly inside an edge.
    fn assert_no_t_junctions(reals: &[Obj], verts: &BTreeSet<Kp>) {
        let mut grid: HashMap<(i64, i64), Vec<Kp>> = HashMap::new();
        for &v in verts {
            let (x, y) = pval(v);
            let key = (x.div_euclid(4.0) as i64, y.div_euclid(4.0) as i64);
            grid.entry(key).or_default().push(v);
        }
        for o in reals {
            let vs = tile_verts(o.ty, o.rot, o.pos);
            let n = vs.len();
            for i in 0..n {
                let (a, b) = (vs[i], vs[(i + 1) % n]);
                let (ax, ay) = pval(a);
                let (bx, by) = pval(b);
                let gx0 = (ax.min(bx)).div_euclid(4.0) as i64 - 1;
                let gx1 = (ax.max(bx)).div_euclid(4.0) as i64 + 1;
                let gy0 = (ay.min(by)).div_euclid(4.0) as i64 - 1;
                let gy1 = (ay.max(by)).div_euclid(4.0) as i64 + 1;
                for gx in gx0..=gx1 {
                    for gy in gy0..=gy1 {
                        for &v in grid.get(&(gx, gy)).into_iter().flatten() {
                            if v == a || v == b {
                                continue;
                            }
                            if !is_zero(pcross(psub(b, a), psub(v, a))) {
                                continue;
                            }
                            // collinear: strictly inside would be a T-junction
                            let d = kval(pdot(psub(v, a), psub(b, a)));
                            assert!(
                                !(d > 1e-11 && d < 1.0 - 1e-11),
                                "T-junction: vertex strictly inside a unit edge"
                            );
                        }
                    }
                }
            }
        }
    }

    /// Exact vertex-fan check: at every vertex the tile corners form
    /// disjoint angular sectors; a single closed cycle spanning all 20
    /// classes is an interior vertex, one or more open chains are
    /// boundary vertices (pinches are legal), anything else is a fault.
    fn assert_vertex_fans(reals: &[Obj]) {
        let mut corners: BTreeMap<Kp, Vec<(u8, u8)>> = BTreeMap::new();
        for o in reals {
            let vs = tile_verts(o.ty, o.rot, o.pos);
            let n = vs.len();
            for i in 0..n {
                let cur = vs[i];
                let prev = vs[(i + n - 1) % n];
                let next = vs[(i + 1) % n];
                let oc = dir_class(psub(next, cur));
                let ic = dir_class(psub(prev, cur));
                assert!(oc >= 0 && ic >= 0, "non-canonical edge direction");
                corners.entry(cur).or_default().push((oc as u8, ic as u8));
            }
        }
        for (v, secs) in &corners {
            let mut by_out: BTreeMap<u8, u8> = BTreeMap::new();
            let mut overlap = false;
            for &(oc, ic) in secs {
                if by_out.insert(oc, ic).is_some() {
                    overlap = true;
                    break;
                }
            }
            assert!(!overlap, "overlapping corners at vertex {v:?}");
            let outs: BTreeSet<u8> = by_out.keys().copied().collect();
            let ics: BTreeSet<u8> = by_out.values().copied().collect();
            let heads: Vec<u8> = outs.difference(&ics).copied().collect();
            let starts: Vec<u8> = if heads.is_empty() {
                vec![*outs.iter().next().unwrap()]
            } else {
                heads.clone()
            };
            let mut visited: BTreeSet<u8> = BTreeSet::new();
            let mut total = 0u32;
            let mut cycles = 0;
            let mut ok = true;
            for &h in &starts {
                let mut cur = h;
                while let Some(&ic) = by_out.get(&cur) {
                    if !visited.insert(cur) {
                        ok = false;
                        break;
                    }
                    total += ((ic + 20 - cur) % 20) as u32;
                    if ic == h {
                        if visited.len() < secs.len() {
                            ok = false;
                        }
                        cycles += 1;
                        break;
                    }
                    cur = ic;
                }
                if !ok {
                    break;
                }
            }
            assert!(ok && visited.len() == secs.len(), "bad fan at vertex {v:?}");
            let interior = cycles == 1 && heads.is_empty() && total == 20;
            assert!(
                interior || cycles == 0,
                "vertex {v:?} neither interior nor boundary"
            );
        }
    }

    /// Exact 10-fold rotational symmetry (canonical per type: HEX/BOW
    /// have 180° symmetry, DEC 36°).
    fn assert_10fold_symmetry(reals: &[Obj]) {
        let sym = |ty: u8| match ty {
            3 => 2u8,
            _ => 10u8,
        };
        let canon_set = |items: &[Obj]| -> HashSet<(u8, Kp, u8)> {
            items
                .iter()
                .map(|o| (o.ty, o.pos, o.rot % sym(o.ty)))
                .collect()
        };
        let base = canon_set(reals);
        for steps in 1..10 {
            let rotated: HashSet<(u8, Kp, u8)> = reals
                .iter()
                .map(|o| {
                    (
                        o.ty,
                        rot_kp((2 * steps) % 20, o.pos),
                        (o.rot + (2 * steps) as u8) % 20 % sym(o.ty),
                    )
                })
                .collect();
            assert_eq!(rotated, base, "10-fold symmetry broken at {steps} steps");
        }
    }

    /// Full structural battery on an exact patch.
    fn structural_battery(reals: &[Obj], want_counts: [usize; 3], label: &str) {
        // census
        let mut counts = [0usize; 3];
        for o in reals {
            match o.ty {
                1 => counts[0] += 1,
                2 => counts[1] += 1,
                3 => counts[2] += 1,
                _ => panic!("{label}: marker among reals"),
            }
        }
        assert_eq!(counts, want_counts, "{label}: tile census");
        let (edges, verts, boundary) = edge_census(reals);
        assert_no_t_junctions(reals, &verts);
        assert_vertex_fans(reals);
        // Euler characteristic: connected, no holes (outer face included).
        // `edges` is the directed map: each interior undirected edge
        // appears twice (once per orientation), each boundary edge once,
        // so the undirected count is (len + boundary) / 2.
        let e_und = (edges.len() + boundary) / 2;
        let chi = verts.len() as i64 - e_und as i64 + reals.len() as i64 + 1;
        assert_eq!(chi, 2, "{label}: Euler characteristic {chi}");
        assert_10fold_symmetry(reals);
    }

    /// Generations 1 and 2 of the full lineage, verified end to end in
    /// exact arithmetic (the Python prototype's battery, re-run in Rust).
    #[test]
    fn generations_one_and_two_are_valid() {
        let seed = seed_objs();
        let mut g1_full: Vec<Obj> = Vec::with_capacity(1024);
        inflate_into(&seed, &mut g1_full);
        let (g1, dup1) = dedup_count(&g1_full);
        assert_eq!(dup1, 0, "gen1 duplicate tiles");
        assert_eq!(g1.len(), 211);
        assert_eq!(g1_full.iter().filter(|o| o.ty == 0).count(), 660);
        structural_battery(&g1, [90, 80, 41], "gen1");

        let mut g2_full: Vec<Obj> = Vec::with_capacity(1 << 17);
        inflate_into(&g1_full, &mut g2_full);
        let (g2, dup2) = dedup_count(&g2_full);
        assert_eq!(dup2, 0, "gen2 duplicate tiles");
        assert_eq!(g2.len(), 16531);
        structural_battery(&g2, [7350, 6740, 2441], "gen2");

        // marker mechanism: generation 2's markers (deduplicated) are
        // exactly the undirected edge set of the generation-2 patch.
        let mut mark_set: BTreeSet<(u8, Kp)> = BTreeSet::new();
        let mut mark_dups = 0;
        for o in &g2_full {
            if o.ty == 0 && !mark_set.insert((o.rot, o.pos)) {
                mark_dups += 1;
            }
        }
        assert_eq!(mark_dups, 0, "gen2 duplicate markers");
        let edge_set: BTreeSet<(Kp, Kp)> = g2
            .iter()
            .flat_map(|o| {
                let vs = tile_verts(o.ty, o.rot, o.pos);
                let n = vs.len();
                (0..n).map(move |i| {
                    let (a, b) = (vs[i], vs[(i + 1) % n]);
                    if a <= b {
                        (a, b)
                    } else {
                        (b, a)
                    }
                })
            })
            .collect();
        let mark_segs: BTreeSet<(Kp, Kp)> = mark_set
            .iter()
            .map(|&(mr, mid)| {
                let h = rot_kp(mr as usize, (HALF, ZERO));
                let a = psub(mid, h);
                let b = padd(mid, h);
                if a <= b {
                    (a, b)
                } else {
                    (b, a)
                }
            })
            .collect();
        assert_eq!(mark_segs.len(), edge_set.len());
        assert_eq!(mark_segs, edge_set, "gen2 markers != patch edges");

        // total area matches the census-frequency identity
        let area: f64 = g2
            .iter()
            .map(|o| match o.ty {
                3 => AREA_DEC,
                1 => AREA_HEX,
                _ => AREA_BOW,
            })
            .sum();
        let want = 2441.0 * AREA_DEC + 7350.0 * AREA_HEX + 6740.0 * AREA_BOW;
        assert!((area - want).abs() <= 1e-9 * want);
    }

    fn dedup_count(objs: &[Obj]) -> (Vec<Obj>, usize) {
        let mut seen: HashSet<[i64; 10]> = HashSet::with_capacity(objs.len());
        let mut out = Vec::new();
        let mut dups = 0;
        for &o in objs {
            if o.ty == 0 {
                continue;
            }
            if seen.insert(obj_key(&o)) {
                out.push(o);
            } else {
                dups += 1;
            }
        }
        (out, dups)
    }

    /// The window cascade reproduces the full lineage exactly at
    /// generation 2, on and off the origin.
    #[test]
    fn cascade_matches_full_generation() {
        let seed = seed_objs();
        let mut g1_full: Vec<Obj> = Vec::new();
        inflate_into(&seed, &mut g1_full);
        let mut g2_full: Vec<Obj> = Vec::new();
        inflate_into(&g1_full, &mut g2_full);
        let full = dedup_count(&g2_full).0;

        for region in [
            (-30.0, 30.0, -30.0, 30.0),
            (40.0, 90.0, -20.0, 30.0),
            (-100.0, -50.0, 60.0, 110.0),
        ] {
            let pruned = build_reals(2, region);
            let inside = |o: &Obj| {
                let (x, y) = pval(o.pos);
                region.0 <= x && x <= region.1 && region.2 <= y && y <= region.3
            };
            // Compare on the strict region: the cascade legitimately
            // retains centers within the emit margin (they may still
            // intersect the view), the full lineage is filtered to match.
            let ka: HashSet<[i64; 10]> = full.iter().filter(|o| inside(o)).map(obj_key).collect();
            let kb: HashSet<[i64; 10]> = pruned.iter().filter(|o| inside(o)).map(obj_key).collect();
            assert_eq!(ka, kb, "cascade != full lineage in {region:?}");
        }
    }

    /// The frozen core: generations 2 and 3 produce identical tiles
    /// within the stable radius (measured rho_2 = 79; the test uses 20).
    #[test]
    fn core_is_depth_stable() {
        let region = (-20.0, 20.0, -20.0, 20.0);
        let g2 = build_reals(2, region);
        let g3 = build_reals(3, region);
        let k2: HashSet<[i64; 10]> = g2.iter().map(obj_key).collect();
        let k3: HashSet<[i64; 10]> = g3.iter().map(obj_key).collect();
        assert_eq!(k2, k3, "core tiles differ between depths 2 and 3");
    }

    /// Views at increasing distance are covered exactly (clipped-area
    /// acceptance), including off-origin boxes served at depths 2-5.
    /// (Area-based verification is only numerically meaningful below
    /// ~1e5 in tiling coordinates — f64 shoelace error grows like
    /// (coordinate)²·ulp — so the maximum-depth regime is verified
    /// structurally in [`deepest_depth_patch_is_structurally_valid`].)
    #[test]
    fn views_are_covered_at_depth() {
        let t = GirihQuasiperiodicTiling;
        let mut p = ParamSet::default_for(t.params());
        p.set(
            crate::lattice::SCALE_ID,
            tess_core::params::ParamValue::Float(1.0),
        );
        for (cx, cy, w, h) in [
            (0.0, 0.0, 15.0, 15.0),
            (47.3, -91.2, 20.0, 20.0),
            (500.0, 300.0, 60.0, 60.0),
            (-1500.0, 800.0, 80.0, 80.0),
            (6000.0, -4000.0, 80.0, 80.0),
        ] {
            let region = BBox::new(Vec2::new(cx - w, cy - h), Vec2::new(cx + w, cy + h));
            let r = t.generate(&p, &Query { region });
            assert!(r.message.is_none(), "view ({cx},{cy}): {:?}", r.message);
            // exact coverage: sum of clipped areas == region area
            let mut covered = 0.0;
            for tile in &r.tiles {
                if let Some(c) = tile.poly.clipped_to(&region) {
                    covered += c.area();
                }
            }
            let want = region.area();
            assert!(
                (covered - want).abs() <= 1e-6 * want,
                "view ({cx},{cy}): covered {covered} != {want}"
            );
        }
    }

    /// The maximum depth serves far views (rcorr ~ 7.2e10 needs the
    /// full depth 12; this is also the i64 headroom exercise —
    /// position coefficients reach ~1e13 and the raw products inside
    /// `kmul` stay below ~3e16, inside i64::MAX = 9.2e18).  Clipped-area
    /// accounting is meaningless at these magnitudes, so the patch is
    /// verified structurally in exact arithmetic instead: unit edges,
    /// no same-direction duplicates, every interior edge matched,
    /// no T-junctions, legal vertex fans, and core density (the box is
    /// deep inside the frozen core).
    #[test]
    fn deepest_depth_patch_is_structurally_valid() {
        let (cx, cy) = (6.0e10, -4.0e10);
        let region = (cx - 20.0, cx + 20.0, cy - 20.0, cy + 20.0);
        let reals = build_reals(12, region);
        assert!(
            !reals.is_empty(),
            "depth 12 produced no tiles at rcorr 7.2e10"
        );
        // density: the 43.5x43.5 retained box is deep inside the frozen
        // core, so tiles ≈ area / mean area (~560 ± rim slack)
        let n = reals.len();
        assert!((300..=800).contains(&n), "unexpected density: {n} tiles");
        let (_, verts, _) = edge_census(&reals);
        assert_no_t_junctions(&reals, &verts);
        assert_vertex_fans(&reals);
    }

    /// Guards: an empty view, an over-large view, and a view beyond the
    /// generated radius all report a message instead of tiles.
    #[test]
    fn view_guards() {
        let t = GirihQuasiperiodicTiling;
        let mut p = ParamSet::default_for(t.params());
        p.set(
            crate::lattice::SCALE_ID,
            tess_core::params::ParamValue::Float(1.0),
        );
        // degenerate
        let r = t.generate(
            &p,
            &Query {
                region: BBox::new(Vec2::new(5.0, 5.0), Vec2::new(5.0, 5.0)),
            },
        );
        assert_eq!(r.message, Some("empty view"));
        // too many tiles
        let r = t.generate(
            &p,
            &Query {
                region: BBox::new(Vec2::new(-3000.0, -3000.0), Vec2::new(3000.0, 3000.0)),
            },
        );
        assert_eq!(r.message, Some("too many tiles for this view — zoom in"));
        // beyond MAX_DEPTH coverage
        let r = t.generate(
            &p,
            &Query {
                region: BBox::new(Vec2::new(1e12, -10.0), Vec2::new(1e12 + 20.0, 10.0)),
            },
        );
        assert_eq!(r.message, Some("too many tiles for this view — zoom in"));
    }
}
